const input = items[0]?.json ?? {};

const action =
  typeof input.action === 'string'
    ? input.action.trim()
    : '';

const auditId =
  typeof input.audit_id === 'string'
    ? input.audit_id.trim()
    : '';

const requestId =
  typeof input.request_id === 'string'
    ? input.request_id.trim()
    : '';

const toolName =
  typeof input.tool_name === 'string'
    ? input.tool_name.trim()
    : '';

const status =
  typeof input.status === 'string'
    ? input.status.trim()
    : '';

const errorCode =
  typeof input.error_code === 'string'
    ? input.error_code.trim()
    : '';

const errorMessage =
  typeof input.error_message === 'string'
    ? input.error_message.trim()
    : '';

const clientName =
  typeof input.client_name === 'string'
    ? input.client_name.trim()
    : '';

const durationMs =
  input.duration_ms === undefined ||
  input.duration_ms === null ||
  input.duration_ms === ''
    ? null
    : Number(input.duration_ms);

const uuidRegex =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

let argumentsJson = input.arguments_json ?? {};

if (
  typeof argumentsJson !== 'object' ||
  Array.isArray(argumentsJson) ||
  argumentsJson === null
) {
  argumentsJson = {};
}

let inputValid = false;
let validationError = null;

if (action === 'start') {
  inputValid =
    toolName.length > 0 &&
    (!requestId || uuidRegex.test(requestId));

  if (!inputValid) {
    validationError =
      'start requires tool_name and request_id must be a UUID when provided';
  }
} else if (action === 'finish') {
  inputValid =
    uuidRegex.test(auditId) &&
    ['succeeded', 'failed'].includes(status) &&
    (
      durationMs === null ||
      (Number.isInteger(durationMs) && durationMs >= 0)
    );

  if (!inputValid) {
    validationError =
      'finish requires valid audit_id, status succeeded|failed, and non-negative integer duration_ms';
  }
} else {
  validationError = 'action must be start or finish';
}

return [
  {
    json: {
      action,
      audit_id: auditId || null,
      request_id: requestId || null,
      tool_name: toolName || null,
      arguments_json: argumentsJson,
      status: status || null,
      error_code: errorCode || null,
      error_message: errorMessage || null,
      duration_ms: durationMs,
      client_name: clientName || null,
      input_valid: inputValid,
      validation_error: validationError
    }
  }
];

return [
  {
    json: {
      success: false,
      error: {
        code: 'INVALID_INPUT',
        message: $json.validation_error ?? 'Invalid audit input'
      }
    }
  }
];
